seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">"))
N=len(seq)

def rc(s):
    return s.translate(str.maketrans("ACGT","TGCA"))[::-1]

# find long inverted repeats (palindromic-ish): search for a substring and its revcomp elsewhere
best=[]
for L in range(10, 41):
    seen={}
    for i in range(0, N-L+1):
        sub=seq[i:i+L]
        seen.setdefault(sub, []).append(i)
    for sub, poss in seen.items():
        r=rc(sub)
        if r in seen and r!=sub:
            for i in poss:
                for j in seen[r]:
                    d=j-i
                    if d>L:  # non-overlapping, inverted orientation with r after
                        best.append((L, i, j, d))
# report the top inverted repeats by length, non-redundant
best.sort(key=lambda x:-x[0])
seen_combo=set()
out=[]
for L,i,j,d in best:
    key=(i//5, j//5)
    if key in seen_combo: continue
    seen_combo.add(key)
    out.append((L,i,j,d))
    if len(out)>=15: break
for L,i,j,d in out:
    print(f"L={L:3d}  i={i:5d}  j={j:5d}  span={d:5d}  sub={seq[i:i+L]}  rc={rc(seq[i:i+L])}")
"}

