seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">"))
N=len(seq)
def rc(s): return s.translate(str.maketrans("ACGT","TGCA"))[::-1]

stops={"TAA","TAG","TGA"}
def orfs(s, strand):
    res=[]
    for frame in range(3):
        i=frame
        start=None
        while i+3<=len(s):
            cod=s[i:i+3]
            if cod=="ATG" and start is None:
                start=i
            if cod in stops:
                if start is not None:
                    res.append((start,i+3,(i+3-start)//3,strand))
                    start=None
                # continue? reset start
            i+=3
        # trailing
        if start is not None:
            res.append((start,len(s),len(s)-start,strand))
    return res

allorf = orfs(seq,"+") + orfs(rc(seq),"-")
allorf.sort(key=lambda x:-x[2])
for s,e,ln,st in allorf[:20]:
    print(st, s, e, "len_nt=%d"%ln if st=="+" else "len_nt=%d (on rc, coords %d-%d)"%(ln, N-e, N-s))
"}

