seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">"))
N=len(seq)
comp = str.maketrans("ACGT","TGCA")
def rc(s): return s.translate(comp)[::-1]
rcseq = rc(seq)
from collections import defaultdict
K=6
idx = defaultdict(list)
for j in range(N-K+1):
    idx[rcseq[j:j+K]].append(j)

i=616
kmer=seq[i:i+K]
print("kmer", kmer, "matches", idx.get(kmer))
for j in idx.get(kmer, []):
    rr=0; rmm=0
    while i+rr<N and j+rr<N:
        if seq[i+rr]==rcseq[j+rr]:
            rr+=1
        else:
            rmm+=1; rr+=1
            if rmm > (K+rr)*0.3:
                rr-=1; break
    ll=0; lmm=0
    while i-ll>0 and j-ll>0:
        if seq[i-ll-1]==rcseq[j-ll-1]:
            ll+=1
        else:
            lmm+=1; ll+=1
            if lmm > (K+ll)*0.3:
                ll-=1; break
    total=ll+rr; totmm=lmm+rmm
    s1=i-ll; e1=i+rr; s2=N-j-rr; e2=N-j+ll
    print("j",j,"ll",ll,"rr",rr,"total",total,"mm",totmm,"s1,e1",s1,e1,"s2,e2",s2,e2, "s1<s2", s1<s2, "ratio", totmm/total if total else None)
"}

