import random
random.seed(1)
comp=str.maketrans("ACGT","TGCA")
def rc(s): return s.translate(comp)[::-1]
base="".join(random.choice("ACGT") for _ in range(3000))
S="TTGACGGATCCAGTACGTACCTGAA"
synth = base[:1000] + S + base[1000:2000] + rc(S) + base[2000:]
N=len(synth); rcs=synth.translate(comp)[::-1]
best=[]
for o in range(12, N-12):
    n=min(N, len(rcs)-o)
    run=0
    for i in range(n):
        if synth[i]==rcs[i+o]:
            run+=1
        else:
            if run>=12: best.append((run,i-run))
            run=0
    if run>=12: best.append((run,n-run))
best.sort(reverse=True)
print("synthetic 25bp-TIR test -> longest exact inverted runs:", best[:3])
print("(should show a 25 bp hit)")

# also test 25bp TIR with 3 mismatches
S2="TTGACGGATCCAGTACGTACCTGTA"
synth2 = base[:1000] + S2 + base[1000:2000] + rc(S2) + base[2000:]
rcs2 = synth2.translate(comp)[::-1]
